package com.mirigangneung.course.service;
import com.mirigangneung.common.error.ApiException;import com.mirigangneung.course.domain.*;import com.mirigangneung.course.dto.*;import com.mirigangneung.course.recommendation.*;import com.mirigangneung.course.repository.*;import com.mirigangneung.place.domain.Place;import com.mirigangneung.place.service.PlaceService;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;
@Service public class CourseService {private final CourseRepository courses;private final CourseStopRepository stops;private final PlaceService places;private final CourseRecommendationEngine engine;public CourseService(CourseRepository c,CourseStopRepository s,PlaceService p,CourseRecommendationEngine e){courses=c;stops=s;places=p;engine=e;}
 @Transactional public CourseResponse create(CreateCourseRequest r){if(!"custom".equals(r.duration())&&(r.startDate()!=null||r.endDate()!=null)){}if("custom".equals(r.duration())&&(r.startDate()==null||r.endDate()==null||r.endDate().isBefore(r.startDate())))throw new ApiException("INVALID_REQUEST",HttpStatus.BAD_REQUEST,"custom 기간이 올바르지 않습니다.");List<Place> selected=r.placeIds().stream().map(places::find).toList();Place one=places.find(r.onePickId());if(selected.stream().noneMatch(p->p.getId().equals(one.getId())))throw new ApiException("INVALID_REQUEST",HttpStatus.BAD_REQUEST,"onePickId는 placeIds에 포함되어야 합니다.");Course c=courses.save(new Course(r.duration(),r.startDate(),r.endDate()));List<Place> result=engine.recommend(selected,one,r.types(),r.companion(),r.duration());int i=1;for(Place p:result)stops.save(new CourseStop(c,p,i++,p.getId().equals(one.getId())));return response(c);}
 @Transactional(readOnly=true) public CourseResponse get(String id){return response(find(id));}@Transactional public void delete(String id){courses.delete(find(id));}@Transactional public ShareResponse share(String id){Course c=find(id);String token=UUID.randomUUID().toString().replace("-","")+UUID.randomUUID().toString().replace("-","");c.share(hash(token),OffsetDateTime.now().plusDays(7));return new ShareResponse(token,"/share/courses/"+token,c.getShareExpiresAt());}@Transactional(readOnly=true)public CourseResponse shared(String token){Course c=courses.findByShareTokenHash(hash(token)).orElseThrow(()->new ApiException("COURSE_NOT_FOUND",HttpStatus.NOT_FOUND,"공유 코스를 찾을 수 없습니다."));if(c.getShareExpiresAt()==null||c.getShareExpiresAt().isBefore(OffsetDateTime.now()))throw new ApiException("COURSE_NOT_FOUND",HttpStatus.NOT_FOUND,"공유 코스를 찾을 수 없습니다.");return response(c);}@Transactional public void revoke(String id){find(id).revokeShare();}private Course find(String id){try{return courses.findById(UUID.fromString(id)).orElseThrow(()->notFound());}catch(Exception e){throw notFound();}}private CourseResponse response(Course c){return CourseResponse.from(c,stops.findByCourseOrderBySequenceAsc(c));}private ApiException notFound(){return new ApiException("COURSE_NOT_FOUND",HttpStatus.NOT_FOUND,"코스를 찾을 수 없습니다.");}private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}}
